import{_ as e,o,c as a,a2 as s}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Context Compaction","description":"","frontmatter":{},"headers":[],"relativePath":"guides/compaction.md","filePath":"guides/compaction.md","lastUpdated":1790952322000}'),n={name:"guides/compaction.md"};function i(r,t,c,d,l,h){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="context-compaction" tabindex="-1">Context Compaction <a class="header-anchor" href="#context-compaction" aria-label="Permalink to &quot;Context Compaction&quot;">​</a></h1><p><strong>Context Compaction</strong> reduces the prompt footprint of a single conversation session by summarizing older turns and keeping the active context smaller.</p><p>This page is about <strong>session context</strong>, not long-term memory storage. If you want to merge or rewrite stored memories in a memory provider, see <a href="./memory.html">Bot Memory Management</a>.</p><hr><h2 id="compaction-is-on-by-default" tabindex="-1">Compaction Is On By Default <a class="header-anchor" href="#compaction-is-on-by-default" aria-label="Permalink to &quot;Compaction Is On By Default&quot;">​</a></h2><p>New bots ship with automatic context compaction <strong>enabled and zero-config</strong>. You do not need to pick a threshold, a ratio, or a summarization model — Memoh sizes everything relative to the chat model&#39;s <code>context_window</code>:</p><ul><li>When the compactable session history passes about <strong>50%</strong> of the model&#39;s context window, Memoh compacts in the <strong>background</strong> after the turn.</li><li>If a session grows past about <strong>75%</strong> before the background pass catches up, Memoh compacts <strong>synchronously</strong> before sending the next turn.</li><li>Either path aims to bring the raw history back down to about <strong>40%</strong> of the window.</li></ul><p>The only real prerequisite: the bot&#39;s chat model must declare a <code>context_window</code> in its model settings. Without it, the automatic policy has no budget to work against and never triggers. See <a href="./../integrations/providers/llm.html">Providers And Models</a>.</p><p>Bots created before this default changed keep their stored settings and behave as configured (see legacy mode below).</p><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>The bot&#39;s compaction settings still exist for tuning and overrides:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>On by default. Turn off to disable automatic compaction for this bot.</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>Input-token threshold. <code>0</code> (the default) means the automatic model-relative policy above. A value <strong>greater than 0</strong> switches to the legacy absolute-threshold mode.</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>How aggressively to reduce the session. Only used in legacy mode — the field is hidden while the threshold is <code>0</code>.</td></tr><tr><td><strong>Compaction Model</strong></td><td>Optional dedicated summarization model. Defaults to the chat model; you can clear an override back to <strong>Use chat model (default)</strong>.</td></tr></tbody></table><h3 id="choosing-a-compaction-model" tabindex="-1">Choosing A Compaction Model <a class="header-anchor" href="#choosing-a-compaction-model" aria-label="Permalink to &quot;Choosing A Compaction Model&quot;">​</a></h3><p>Any enabled chat model can summarize, with one restriction: the provider must respect output-token limits. <strong>OpenAI Codex models cannot be used as the summarizer</strong> — the model dropdown filters them out.</p><p>This matters when a bot&#39;s main chat model is a Codex model: automatic compaction quietly stands down because there is nothing valid to inherit. Assign an explicit Compaction Model in that case.</p><hr><h2 id="immediate-compaction" tabindex="-1">Immediate Compaction <a class="header-anchor" href="#immediate-compaction" aria-label="Permalink to &quot;Immediate Compaction&quot;">​</a></h2><p>You can trigger compaction immediately for the current session in two ways:</p><h3 id="from-the-session-status-panel" tabindex="-1">From The Session Status Panel <a class="header-anchor" href="#from-the-session-status-panel" aria-label="Permalink to &quot;From The Session Status Panel&quot;">​</a></h3><ol><li>Open the active conversation.</li><li>Open the session status panel.</li><li>Click <strong>Compact Now</strong>.</li></ol><p>The status panel also shows the current context usage, cache hit rate, and used skills, which helps you decide whether compaction is useful right now.</p><h3 id="from-slash-commands" tabindex="-1">From Slash Commands <a class="header-anchor" href="#from-slash-commands" aria-label="Permalink to &quot;From Slash Commands&quot;">​</a></h3><p>Run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>or:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact run</span></span></code></pre></div><p>Manual compaction compacts as much of the session as possible (rather than stopping at the automatic target) and bypasses the short cooldown that automatic compaction observes after a failed attempt.</p><hr><h2 id="what-compaction-preserves" tabindex="-1">What Compaction Preserves <a class="header-anchor" href="#what-compaction-preserves" aria-label="Permalink to &quot;What Compaction Preserves&quot;">​</a></h2><p>The summarizer works on typed conversation records, which keeps the summary faithful:</p><ul><li>Tool calls and their results are never split apart — a tool exchange either stays in the raw history or is summarized as a whole.</li><li>Media are summarized as <code>[image]</code> / <code>[file]</code> markers rather than raw data.</li><li>Summaries that come back empty, truncated, or not actually smaller than the original are rejected instead of being stored.</li><li>In sessions that run on multiple workspaces, the summary keeps track of which workspace each part of the conversation happened on.</li></ul><p>Compaction applies to normal chat sessions and to <strong>discuss</strong> and pipeline-based conversations as well.</p><hr><h2 id="status-and-logs" tabindex="-1">Status And Logs <a class="header-anchor" href="#status-and-logs" aria-label="Permalink to &quot;Status And Logs&quot;">​</a></h2><p>The <strong>Compaction</strong> tab in the bot detail page provides an audit trail for context compaction runs.</p><p>Typical fields include:</p><ul><li><strong>Status</strong> — whether the compaction finished successfully or failed</li><li><strong>Summary</strong> — the compacted summary text or a summary preview</li><li><strong>Message Count</strong> — how many messages were involved</li><li><strong>Started / Completed Time</strong> — when the run happened</li><li><strong>Model / Usage</strong> — metadata about the model and token usage when available</li></ul><p>The log list is useful when you want to verify that automatic compaction is actually running or diagnose a failure.</p><h3 id="common-failure-reasons" tabindex="-1">Common Failure Reasons <a class="header-anchor" href="#common-failure-reasons" aria-label="Permalink to &quot;Common Failure Reasons&quot;">​</a></h3><p>When compaction cannot run, Memoh reports <code>compaction.model_unavailable</code> with a specific reason: the compaction model is not configured, not a chat model, disabled, its provider is disabled, the provider does not support output limits (Codex), or the model has no known context window. <code>/compact</code> reports the same conditions inline in chat.</p><hr><h2 id="relationship-to-context-window" tabindex="-1">Relationship To <code>context_window</code> <a class="header-anchor" href="#relationship-to-context-window" aria-label="Permalink to &quot;Relationship To `context_window`&quot;">​</a></h2><p>Memoh tracks the current session against the selected chat model&#39;s <code>context_window</code>.</p><p>You can see this in:</p><ul><li>the app&#39;s session status panel</li><li>the <code>/status</code> slash command</li></ul><p>Context usage is an estimate (roughly four characters per token), so treat the percentages as guidance rather than exact numbers.</p><hr><h2 id="context-compaction-vs-memory-compaction" tabindex="-1">Context Compaction vs Memory Compaction <a class="header-anchor" href="#context-compaction-vs-memory-compaction" aria-label="Permalink to &quot;Context Compaction vs Memory Compaction&quot;">​</a></h2><p>These two features sound similar but solve different problems:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Scope</th><th>Trigger</th><th>Result</th></tr></thead><tbody><tr><td><strong>Context Compaction</strong></td><td>One active session</td><td>Automatic, session panel, or <code>/compact</code></td><td>Summarizes older chat history for future turns</td></tr><tr><td><strong>Memory Compaction</strong></td><td>Long-term memory provider</td><td>Memory tab</td><td>Rewrites stored memory entries</td></tr></tbody></table><p>Use <strong>Context Compaction</strong> when one conversation has become too large.</p><p>Use <strong>Memory Compaction</strong> when the bot&#39;s stored memories themselves have become noisy or redundant.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>To inspect session runtime information, see <a href="./sessions.html">Sessions</a>.</li><li>To understand slash-triggered compaction, see <a href="./slash-commands.html">Slash Commands</a>.</li><li>To manage long-term memory instead of session context, see <a href="./memory.html">Bot Memory Management</a>.</li></ul>',56)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
